      }}
    >
      <Box
        sx={{
          width: 12,
          height: 12,
          borderRadius: '50%',
          bgcolor: getStatusColor(statusState),
          boxShadow: `0 0 10px ${getStatusShadow(statusState)}`,
          animation: statusState !== 'INACTIVE' ? 'pulse 1s ease-in-out infinite' : 'none',
          '@keyframes pulse': {
            '0%, 100%': { opacity: 1, transform: 'scale(1)' },
            '50%': { opacity: 0.7, transform: 'scale(1.2)' }
          }
        }}
      />

      <Typography
        sx={{
          fontSize: '0.9rem',
          fontWeight: 600,
          color: '#ffffff',
          textTransform: 'uppercase',
          letterSpacing: '0.5px'
        }}
      >
        {statusState}
      </Typography>

      <Typography
        sx={{
          fontFamily: 'Courier New, monospace',
          fontSize: '0.8rem',
          color: '#00ff88',
          ml: 'auto'
        }}
      >
        {fieldStrength.toFixed(2)}T
      </Typography>

      <Box
        sx={{
          width: 80,
          height: 4,
          bgcolor: 'rgba(255, 255, 255, 0.1)',
          borderRadius: 1,
          overflow: 'hidden'
        }}
      >
        <Box
          sx={{
            width: `${Math.min(100, fieldCoherence * 100)}%`,
