              }}
            >
              Play
            </Button>

            <Button
              variant="contained"
              color="error"
              onClick={onStop}
              startIcon={<StopIcon />}
              fullWidth
              sx={{
                py: 1,
                background: 'linear-gradient(45deg, #ff0066, #ff6b00)',
