                    </Typography>

                    {customPreset.transitions.map((transition, index) => (
                        <Paper key={index} elevation={1} sx={{p: 2, mb: 2, bgcolor: 'rgba(0,0,0,0.05)'}}>
                            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                                <Typography variant="subtitle1" fontWeight="bold">
                                    Transition {index + 1}
                                </Typography>
                                {customPreset.transitions.length > 1 && (
                                    <IconButton
                                        size="small"
                                        onClick={() => removeTransition(index)}
                                        color="error"
                                    >
                                        <DeleteIcon/>
                                    </IconButton>
                                )}
                            </Box>

                            <Grid container spacing={2}>
                                <Grid size={{xs: 6, md: 3}}>
                                    <TextField
                                        fullWidth
                                        label="Left Ear (Hz)"
                                        type="text"
                                        value={transition.left_ear_hz}
                                        onChange={(e) => {
                                            updateTransition(index, 'left_ear_hz', e.target.value);
                                        }}
                                        size="small"
                                    />
                                </Grid>

                                <Grid size={{xs: 6, md: 3}}>
                                    <TextField
                                        fullWidth
                                        label="Right Ear (Hz)"
                                        type="text"
                                        value={transition.right_ear_hz}
                                        onChange={(e) => {
                                            updateTransition(index, 'right_ear_hz', e.target.value);
                                        }}
                                        size="small"
                                    />
                                </Grid>

                                <Grid size={{xs: 6, md: 3}}>
                                    <TextField
                                        fullWidth
                                        label="Beat Frequency (Hz)"
                                        type="number"
                                        value={transition.frequency_hz}
                                        InputProps={{readOnly: true}}
                                        size="small"
                                        sx={{
                                            '& .MuiInputBase-input': {
                                                backgroundColor: 'rgba(0, 191, 255, 0.1)',
                                                color: '#00bfff',
                                                fontWeight: 'bold'
                                            }
                                        }}
                                    />
                                </Grid>

                                <Grid size={{xs: 6, md: 3}}>
                                    <TextField
                                        fullWidth
                                        label="Wave Type"
                                        value={transition.frequency_type}
                                        InputProps={{readOnly: true}}
                                        size="small"
                                        sx={{
                                            '& .MuiInputBase-input': {
                                                backgroundColor: 'rgba(0, 191, 255, 0.1)',
                                                color: '#00bfff',
                                                fontWeight: 'bold'
                                            }
                                        }}
                                    />
                                </Grid>

                                <Grid size={{xs: 6, md: 6}}>
                                    <TextField
                                        fullWidth
                                        label={`Duration of Transition ${index + 1}`}
                                        type="number"
                                        value={transition.duration_minutes}
                                        onChange={(e) => {
                                            const value = parseInt(e.target.value);
                                            if (!isNaN(value) && value >= 1 && value <= 300) {
                                                updateTransition(index, 'duration_minutes', value);
                                            }
                                        }}
                                        inputProps={{
                                            min: 1,
                                            max: 300,
                                            step: 1
                                        }}
                                        size="small"
                                    />
                                </Grid>

                                <Grid size={{xs: 6, md: 6}}>
                                    <TextField
                                        fullWidth
                                        label="Total Preset Duration"
                                        type="number"
                                        value={customPreset.transitions.slice(index).reduce((sum, t) => sum + t.duration_minutes, 0)}
                                        InputProps={{readOnly: true}}
                                        size="small"
                                        sx={{
                                            '& .MuiInputBase-input': {
                                                backgroundColor: 'rgba(255, 107, 0, 0.1)',
                                                color: '#ff6b00',
                                                fontWeight: 'bold'
                                            }
                                        }}
                                    />
                                </Grid>
                            </Grid>
                        </Paper>
                    ))}

                    <Button
                        variant="outlined"
                        startIcon={<AddIcon/>}
                        onClick={addTransition}
                        sx={{mt: 1, mb: 2}}
                    >
                        Add Transition
                    </Button>

                    <Typography variant="body2" color="textSecondary" align="center">
                        Total Preset
                        Duration: {customPreset.transitions.reduce((sum, t) => sum + t.duration_minutes, 0)} minutes
