          audioContextRef.current = window.__EBL_AUDIO_CONTEXT__;
          analyserNodeRef.current = window.__EBL_ANALYSER_NODE__ || null;
          return window.__EBL_AUDIO_CONTEXT__;
        }
      }

      // 🔥 GLOBAL LOCK CHECK
