(config: Partial<VisualizationConfig> = {}) => {
  const defaultConfig: VisualizationConfig = {
    updateRate: 60,
    enabled: true,
    showSpectrum: true,
    showPeaks: true,
    showAmplitudes: true,
    ...config
  };

  // State management using existing audio types
  const [audioState, setAudioState] = useState<FrontendAudioEngineState >({
    isPlaying: false,
    volume: 0.3,
    leftFreq: 440,
    rightFreq: 444,
    beat_frequency: 4,
    waveform: 'sine',
