  const setReverbMix = useCallback((mix: number) => {
    const clampedMix = Math.max(0, Math.min(1, mix));

    if (spatialEngine.current) {
      spatialEngine.current.setReverbMix(clampedMix);
    }

    setState(prev => ({
      ...prev,
      reverbMix: clampedMix
    }));
  }, []);

  return {
