    const radius = maxRadius * (1 - t * 0.7);

    const x = radius * Math.cos(angle);
    const y = radius * Math.sin(angle);
    const z = (t - 0.5) * height; // -100 to +100

    path.push({ x, y, z });
  }

  return path;
}

