(
  patternConfig: PatternConfig,
  pointCount: number = 500
): Position3D[] => {
  const path: Position3D[] = [];

  // Lorenz attractor parameters
  const sigma = 10;
  const rho = 28;
  const beta = 8/3;
  const dt = 0.01;

  // Initial conditions
  let x = 0.1;
  let y = 0;
  let z = 0;

  const scale = 3;

  for (let i = 0; i < pointCount; i++) {
    // Lorenz equations
    const dx = sigma * (y - x);
    const dy = x * (rho - z) - y;
    const dz = x * y - beta * z;

    x += dx * dt;
    y += dy * dt;
    z += dz * dt;

    path.push({
      x: x * scale,
      y: y * scale,
      z: z * scale
    });
  }

  return path;
}

(
